const esc=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));

export function bindKnowledge(root,k){
 const input=root.querySelector('#knowledge-query');if(!input)return;
 const entries=[...k.domains.map(d=>({...d,label:d.name,group:'Domain'})),...k.topics.map(t=>({...t,label:t.name,group:'Topic',related:t.domain_ids.map(id=>k.domains.find(d=>d.id===id)?.name||id)})),...k.dimensions.flatMap(d=>d.options.map(o=>({...o,group:d.label,rule:d.rule})))];
 const update=()=>{
  const query=input.value.trim().toLowerCase(),rows=entries.filter(x=>[x.id,x.label,x.definition,x.routing_rule,x.group].join(' ').toLowerCase().includes(query));
  root.querySelector('#knowledge-reference').hidden=!!query;
  const results=root.querySelector('#knowledge-results');results.hidden=!query;
  root.querySelector('#knowledge-count').textContent=query?`${rows.length} definitions found`:'';
  results.innerHTML=rows.length?rows.map(x=>`<article class="knowledge-option"><h2>${esc(x.label)}</h2><p class="muted">${esc(x.group)} · <code>${esc(x.id)}</code></p><p>${esc(x.definition)}</p>${x.related?`<p>Related domains: ${x.related.map(name=>`<button class="text-link" data-related-label="${esc(name)}">${esc(name)}</button>`).join(' · ')}</p>`:''}${x.routing_rule||x.rule?`<details><summary>When to use this label</summary><p>${esc(x.routing_rule||x.rule)}</p></details>`:''}</article>`).join(''):'<p>No definitions match. Try a broader word or clear the search.</p>';
  results.querySelectorAll('[data-related-label]').forEach(b=>b.onclick=()=>{input.value=b.dataset.relatedLabel;update();input.focus();});
 };
 input.oninput=update;root.querySelector('#clear-knowledge').onclick=()=>{input.value='';update();input.focus();};
}

// Textareas expose LF even for CRLF files. Preserve source bytes on a revert,
// and retain a consistent CRLF convention for intentional edits.
export function editedFileContent(original, visible) {
 const normalized=original.replace(/\r\n/g,'\n');
 const text=visible.replace(/\r\n/g,'\n');
 if(text===normalized)return original;
 return original.includes('\r\n')&&!normalized.includes('\r')&&!/(?<!\r)\n/.test(original)?text.replace(/\n/g,'\r\n'):text;
}
export function knowledgePage(k){
 const exampleDimensions={record_kind:'record_kinds',target_kind:'target_kinds',conditionality:'conditionalities'};
 const exampleRows=Object.entries(k.example.labels).map(([key,value])=>{
  const dimension=k.dimensions.find(d=>d.id===(exampleDimensions[key]||key));
  const selected=(Array.isArray(value)?value:[value]).map(id=>dimension?.options.find(o=>o.id===id)?.label||id);
  return `<tr><th scope="row">${esc(dimension?.label||key)}</th><td>${selected.map(esc).join(' · ')}</td></tr>`;
 }).join('');
 return `<div class="title-row"><div><div class="eyebrow">KNOWLEDGE & LABELS</div><h1>What every label means</h1><p class="muted">Find a label’s meaning, see an example, or browse the complete reference.</p></div><button data-download-knowledge>Download the codebook</button></div><div class="knowledge-search"><label>Find a label or meaning<input type="search" id="knowledge-query" placeholder="For example: conditional, recovery, finance"></label><button id="clear-knowledge">Clear search</button><span id="knowledge-count" role="status"></span></div><div id="knowledge-results" hidden></div><div id="knowledge-reference"><details class="knowledge-intro"><summary>How domains, topics and other labels fit together</summary><p>A domain is a broad policy area; a topic is a specific subject within it. Other labels describe independent aspects of the same statement.</p><p><strong>Invented example:</strong> “Install flood warning systems by 2030, subject to international finance.” The topic is Early warning and disaster preparedness, within Climate & disaster policy. Separate labels describe a Commitment, the hazard Flood, and an Explicitly conditional target.</p><p>A solar irrigation action may belong to both water and energy topics. It remains one source record.</p></details><section class="paper"><h2>Domains → topics</h2><p class="muted">A topic is the subdomain level. Select supported topics; derive domains from them. One cross-sector commitment still counts once.</p>${k.domains.map(d=>`<details class="knowledge-group" data-knowledge-text="${esc([d.name,d.definition,...k.topics.filter(t=>t.domain_ids.includes(d.id)).map(t=>`${t.id} ${t.name} ${t.definition} ${t.routing_rule}`)].join(' ').toLowerCase())}"><summary>${esc(d.name)} <small>${esc(d.id)}</small></summary><p>${esc(d.definition)}</p>${k.topics.filter(t=>t.domain_ids.includes(d.id)).map(t=>`<article class="knowledge-option"><h3>${esc(t.name)} <code>${esc(t.id)}</code></h3><p>${esc(t.definition)}</p><p class="muted">${esc(t.routing_rule)}</p></article>`).join('')}</details>`).join('')}</section>${[['policy','Policy labels','One statement type; other supported labels may have multiple values.'],['detail','Linked facts and details','Targets, institutions, finance and scope retain their own meaning.'],['evidence','Evidence and processing information','Explain material gaps and uncertainty where they affect interpretation. These are not policy labels.']].map(([category,title,description])=>`<section class="paper method-section"><h2>${title}</h2><p class="muted">${description}</p>${k.dimensions.filter(d=>(d.category||'detail')===category).map(d=>`<details class="knowledge-group" data-knowledge-text="${esc(JSON.stringify(d).toLowerCase())}"><summary>${esc(d.label)} <small>${d.options.length} values</small></summary><h3>${esc(d.question)}</h3><p>${esc(d.rule)}</p>${d.options.map(o=>`<article class="knowledge-option"><h3>${esc(o.label)} <code>${esc(o.id)}</code></h3><p>${esc(o.definition)}</p></article>`).join('')}</details>`).join('')}</section>`).join('')}<section class="paper method-section"><h2>Worked example</h2><p class="badge neutral">${esc(k.example.notice)}</p><p>${esc(k.example.text)}</p><table><tbody>${exampleRows}</tbody></table><p class="muted">${k.example.unknowns.map(esc).join(" · ")}</p></section><section class="method-section"><h2>References and scope</h2><p>${esc(k.status)} · Current codebook ${esc(k.version)}. A saved profile uses its own archived definitions.</p><details><summary>Complete information structure</summary><div class="knowledge-structure">${k.record_structure.map(r=>`<article><h3>${esc(r.name)}</h3><p>${esc(r.meaning)}</p></article>`).join('')}</div></details><p class="muted">${esc(k.scope)}</p>${k.references.map(r=>`<p><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)}</a> — ${esc(r.use)}</p>`).join('')}</section></div>`;
}
export function configPage(pack){
 return `<div class="title-row"><div><div class="eyebrow">EDITABLE METHOD PACKAGE</div><h1>Configuration</h1><p class="muted">For maintainers: edit prompts, labels and settings for future analyses.</p></div></div><p class="callout">Apply method validates and saves these edits for future runs. Historical results keep their original method. Download a copy if you want to keep an unfinished draft.</p><section class="paper"><label class="full-label">Method file<select id="config-file">${pack.files.map(f=>`<option value="${esc(f.path)}">${esc(f.path)}</option>`).join('')}</select></label><p id="config-file-help" class="muted"></p><label class="full-label">Editable contents<textarea class="config-editor" id="config-content" rows="20" spellcheck="false"></textarea></label><p id="config-status" role="status"></p><button id="export-config">Download edited method package</button><details class="method-expand"><summary>Edit topics in a spreadsheet</summary><p>Export topics with <code>python scripts/topic_csv.py export topics.csv</code>. Edit the UTF-8 table, retaining stable IDs. Import with <code>python scripts/topic_csv.py import topics.csv --version 3.1.0 --output topic-draft.json</code>, using your next version number. Import creates a validated draft package; JSON remains authoritative.</p></details><details class="method-expand"><summary>Add or change a label</summary><ol><li>Add its stable ID to <code>config/v2/vocabulary.json</code>, or a topic/domain to <code>taxonomy.json</code>.</li><li>Add the matching meaning and assignment rule to <code>label-guide.json</code>. Topics carry their own definitions and routing rules.</li><li>Increment the affected configuration version. Validate and rebuild schemas, prompt inputs, filters and this guide together.</li><li>New runs use the new method. Existing releases keep their recorded method version.</li></ol></details><details class="method-expand"><summary>Apply the downloaded package locally</summary><pre class="code-sample">python scripts/method_pack.py validate path/to/method-pack.json
python scripts/method_pack.py apply path/to/method-pack.json</pre><p class="muted">The command validates allowed files, definitions and references, rejects stale packages, archives before/after copies, updates local method files and rebuilds derived assets. It does not run a model or publish reports. Use while generation workers are stopped.</p></details><p class="muted">Editable: prompt wording, category definitions, topic mappings, supported label values, option wording/effects/defaults. New task types, statement-type values, conditionalities, section states, target comparators, output-field structures, provider transports and authorization rules require implementation. Definitions and descriptive facets such as hazards can be edited within the supported structure.</p></section>`;
}
